import{useEffect,useMemo,useState}from"react";import{CalendarCheck,BriefcaseBusiness,CheckCircle2,Clock3,ExternalLink,FileText,RefreshCw,XCircle,Phone,Mail,PackageCheck,UserRound,ChevronRight}from"lucide-react";import{getVendorBookings,getVendorApplications,updateBookingStatus,updateApplicationStatus}from"../../api/vendorApi";import{sendOffer}from"../../api/jobApi";import StatusTimeline from"../../components/StatusTimeline";
const badge=s=>{const v=String(s||"").toUpperCase();if(["CONFIRMED","ACCEPTED","COMPLETED","DELIVERED","RETURNED","ATTENDED"].includes(v))return"bg-emerald-50 text-emerald-700";if(["REJECTED","CANCELLED"].includes(v))return"bg-red-50 text-red-700";if(["SHORTLISTED","UNDER_REVIEW","INTERVIEW","PROCESSING","SHIPPED","SCHEDULED","PICKUP"].includes(v))return"bg-indigo-50 text-indigo-700";return"bg-amber-50 text-amber-700"};
const pretty=s=>({ORDER:"Order",BOOKING:"Service booking",SESSION:"Tutor session",RESERVATION:"Reservation",REGISTRATION:"Event registration"}[s]||s||"Request");const fmt=d=>d?new Date(d).toLocaleDateString("en-IN",{day:"2-digit",month:"short",year:"numeric"}):"—";
const actions=(x)=>{const s=x.status,t=String(x.listingType||"").toUpperCase();if(t==="PRODUCT"||x.bookingType==="ORDER"){if(["ORDER_PLACED","PENDING"].includes(s))return[["CONFIRMED","Confirm"],["REJECTED","Reject"]];if(s==="CONFIRMED")return[["PROCESSING","Start processing"],["CANCELLED","Cancel"]];if(s==="PROCESSING")return[["SHIPPED","Mark shipped"]];if(s==="SHIPPED")return[["DELIVERED","Mark delivered"]]}if(t==="EVENT"||x.bookingType==="REGISTRATION"){if(["REGISTERED","PENDING"].includes(s))return[["CONFIRMED","Confirm"],["REJECTED","Reject"]];if(s==="CONFIRMED")return[["ATTENDED","Mark attended"]]}if(t==="PROPERTY"){if(s==="PENDING")return[["VISIT_SCHEDULED","Schedule visit"],["REJECTED","Reject"]];if(s==="VISIT_SCHEDULED")return[["NEGOTIATION","Start negotiation"],["COMPLETED","Complete"]];if(s==="NEGOTIATION")return[["COMPLETED","Complete"]]}if(["RENTAL","VEHICLE_RENTAL"].includes(t)||x.bookingType==="RESERVATION"){if(s==="PENDING")return[["CONFIRMED","Confirm"],["REJECTED","Reject"]];if(s==="CONFIRMED")return[["SCHEDULED","Schedule"],["PICKUP","Mark pickup"]];if(["SCHEDULED","PICKUP"].includes(s))return[["RETURNED","Mark returned"],["COMPLETED","Complete"]]}if(["SERVICE","TUTOR"].includes(t)){if(s==="PENDING")return[["CONFIRMED","Confirm"],["REJECTED","Reject"]];if(s==="CONFIRMED")return[["SCHEDULED","Schedule"]];if(s==="SCHEDULED")return[["COMPLETED","Complete"]]}return[]};
export default function Requests(){const[tab,setTab]=useState("bookings"),[bookings,setBookings]=useState([]),[apps,setApps]=useState([]),[loading,setLoading]=useState(true),[busy,setBusy]=useState(""),[notice,setNotice]=useState(""),[selected,setSelected]=useState(null),[filter,setFilter]=useState("ALL");const load=async()=>{setLoading(true);try{const[b,a]=await Promise.all([getVendorBookings(),getVendorApplications()]);setBookings(dedupe(b.data?.data||[]));setApps(dedupe(a.data?.data||[]))}catch(e){setNotice(e.response?.data?.message||"Unable to load requests.")}finally{setLoading(false)}};useEffect(()=>{load()},[]);const list=useMemo(()=>{const a=tab==="bookings"?bookings:apps;return filter==="ALL"?a:a.filter(x=>x.status===filter)},[tab,bookings,apps,filter]);const change=async(kind,id,status,extra={})=>{setBusy(`${kind}-${id}-${status}`);try{if(kind==="booking")await updateBookingStatus(id,status,extra.note||"");else await updateApplicationStatus(id,status,extra);await load();setSelected(null);setNotice("Status updated successfully.")}catch(e){setNotice(e.response?.data?.message||"Could not update status")}finally{setBusy("")}};const pending=bookings.filter(x=>["PENDING","ORDER_PLACED","REGISTERED"].includes(x.status)).length;const appAction=apps.filter(x=>["SUBMITTED","UNDER_REVIEW","SHORTLISTED"].includes(x.status)).length;return <div className="page-shell vendor-bg"><div className="flex flex-col gap-4 sm:flex-row sm:items-end sm:justify-between"><div><p className="eyebrow">VENDOR OPERATIONS · V16</p><h1 className="page-title">Transaction workflow</h1><p className="mt-2 max-w-3xl text-sm leading-6 text-slate-500">Move every customer request through its category-specific lifecycle and keep a complete status timeline.</p></div><button className="btn-secondary" onClick={load}><RefreshCw size={16}/> Refresh</button></div><div className="mt-7 grid gap-4 sm:grid-cols-2 lg:grid-cols-4"><Stat icon={PackageCheck} label="Transactions" value={bookings.length}/><Stat icon={Clock3} label="Needs action" value={pending}/><Stat icon={BriefcaseBusiness} label="Applications" value={apps.length}/><Stat icon={FileText} label="Application action" value={appAction}/></div>{notice&&<div className="mt-5 rounded-2xl border border-slate-200 bg-white px-4 py-3 text-sm font-semibold text-slate-700">{notice}</div>}<div className="mt-7 card overflow-hidden"><div className="flex flex-col gap-2 border-b border-slate-100 p-2 sm:flex-row"><Tab active={tab==="bookings"} onClick={()=>{setTab("bookings");setFilter("ALL")}} icon={CalendarCheck} label={`Transactions (${bookings.length})`}/><Tab active={tab==="applications"} onClick={()=>{setTab("applications");setFilter("ALL")}} icon={BriefcaseBusiness} label={`Job applications (${apps.length})`}/></div><div className="flex gap-2 overflow-x-auto border-b border-slate-100 p-3"><Filter active={filter==="ALL"} onClick={()=>setFilter("ALL")} text="All"/>{[...new Set((tab==="bookings"?bookings:apps).map(x=>x.status).filter(Boolean))].map(s=><Filter key={s} active={filter===s} onClick={()=>setFilter(s)} text={s}/>)}</div>{loading?<div className="p-14 text-center text-sm text-slate-400">Loading transactions…</div>:tab==="bookings"?<BookingList data={list} busy={busy} change={change} onOpen={x=>setSelected({kind:"booking",item:x})}/>:<ApplicationList data={list} busy={busy} change={change} onOpen={x=>setSelected({kind:"application",item:x})}/>}</div>{selected?.kind==="booking"&&<BookingModal item={selected.item} onClose={()=>setSelected(null)} busy={busy} change={change}/>} {selected?.kind==="application"&&<ApplicationModal item={selected.item} onClose={()=>setSelected(null)} busy={busy} change={change}/>}</div>}
function BookingList({data,busy,change,onOpen}){if(!data.length)return<Empty icon={CalendarCheck} title="No matching transactions" text="New orders, bookings, registrations and reservations will appear here."/>;return<div className="divide-y divide-slate-100">{data.map(x=><div className="p-5 sm:p-6" key={x.id}><div className="flex flex-col gap-5 xl:flex-row xl:items-center xl:justify-between"><div className="min-w-0 flex-1"><div className="flex flex-wrap items-center gap-2"><span className="rounded-lg bg-slate-100 px-2.5 py-1 text-xs font-black">{pretty(x.bookingType)}</span><span className={`status-pill ${badge(x.status)}`}>{x.status}</span><span className="text-xs text-slate-400">{x.listingType}</span></div><div className="mt-3 flex items-center gap-3"><div className="h-16 w-16 shrink-0 overflow-hidden rounded-xl bg-slate-100">{x.listingImage?<img src={x.listingImage} alt="" className="h-full w-full object-cover"/>:<div className="grid h-full place-items-center text-slate-300">▧</div>}</div><div className="min-w-0"><p className="truncate font-bold">{x.listingTitle||`Listing #${x.listingId}`}</p><p className="text-xs text-slate-500">{x.customerName||x.contactName||"Customer"}{x.customerMobile?` · ${x.customerMobile}`:""}</p></div></div><div className="mt-3 flex flex-wrap gap-x-5 gap-y-2 text-sm text-slate-500"><span>Created {fmt(x.createdAt)}</span>{x.bookingDate&&<span>Scheduled {fmt(x.bookingDate)}</span>}{x.amount!=null&&<span>₹{Number(x.amount).toLocaleString("en-IN")}</span>}</div></div><div className="flex flex-wrap gap-2 xl:max-w-lg xl:justify-end"><button className="btn-secondary" onClick={()=>onOpen(x)}>Timeline <ChevronRight size={15}/></button>{actions(x).map(([st,label])=><button key={st} className={`btn-${st==="REJECTED"?"secondary":"primary"} ${st==="REJECTED"?"text-red-600":""}`} disabled={busy===`booking-${x.id}-${st}`} onClick={()=>change("booking",x.id,st)}>{st==="REJECTED"?<XCircle size={16}/>:<CheckCircle2 size={16}/>} {label}</button>)}</div></div></div>)}</div>}
function ApplicationList({data,busy,change,onOpen}){if(!data.length)return<Empty icon={BriefcaseBusiness} title="No matching applications" text="Applications to your published jobs will appear here."/>;return<div className="divide-y divide-slate-100">{data.map(x=><div className="p-5 sm:p-6" key={x.id}><div className="flex flex-col gap-5 xl:flex-row xl:items-center xl:justify-between"><div className="min-w-0 flex-1"><div className="flex flex-wrap items-center gap-2"><span className="rounded-lg bg-indigo-50 px-2.5 py-1 text-xs font-black text-indigo-700">JOB</span><span className={`status-pill ${badge(x.status)}`}>{x.status}</span></div><div className="mt-3 flex items-center gap-3"><div className="h-14 w-14 shrink-0 overflow-hidden rounded-xl bg-slate-100">{x.listingImage?<img src={x.listingImage} alt="" className="h-full w-full object-cover"/>:<BriefcaseBusiness className="m-4 text-slate-300"/>}</div><div className="min-w-0"><p className="truncate font-bold">{x.listingTitle||`Listing #${x.postId}`}</p><p className="text-xs text-slate-400">{x.applicantName||"Applicant"} · Applied {fmt(x.createdAt)}</p></div></div></div><div className="flex flex-wrap gap-2 xl:justify-end"><button className="btn-secondary" onClick={()=>onOpen(x)}>Timeline <ChevronRight size={15}/></button>{x.resumeUrl&&<a className="btn-secondary" href={x.resumeUrl} target="_blank" rel="noreferrer"><ExternalLink size={16}/> Resume</a>}{x.status==="SUBMITTED"&&<button className="btn-secondary" disabled={busy===`application-${x.id}-UNDER_REVIEW`} onClick={()=>change("application",x.id,"UNDER_REVIEW")}>Review</button>}{["SUBMITTED","UNDER_REVIEW"].includes(x.status)&&<button className="btn-secondary" disabled={busy===`application-${x.id}-SHORTLISTED`} onClick={()=>change("application",x.id,"SHORTLISTED")}>Shortlist</button>}{["UNDER_REVIEW","SHORTLISTED"].includes(x.status)&&<button className="btn-secondary" disabled={busy===`application-${x.id}-INTERVIEW`} onClick={()=>{const d=window.prompt("Interview date/time (ISO-8601)");if(d)change("application",x.id,"INTERVIEW",{interviewDate:d,note:"Interview scheduled by vendor"})}}>Interview</button>}{x.status!=="ACCEPTED"&&x.status!=="REJECTED"&&<button className="btn-primary" disabled={busy===`application-${x.id}-ACCEPTED`} onClick={()=>change("application",x.id,"ACCEPTED")}>Select</button>}{x.status==="INTERVIEW"&&<button className="btn-primary" onClick={async()=>{const c=window.prompt("Annual CTC in INR", "800000");if(c){try{await sendOffer(x.id,{annualCtc:Number(c),designation:x.listingTitle,joiningLocation:"Bengaluru",expiresAt:new Date(Date.now()+7*86400000).toISOString(),notes:"Offer generated from ASMJ recruitment workflow"});setNotice("Offer sent successfully.");await load()}catch(e){setNotice(e.response?.data?.message||"Could not send offer")}}}}>Send offer</button>}{x.status!=="REJECTED"&&x.status!=="ACCEPTED"&&<button className="btn-secondary text-red-600" disabled={busy===`application-${x.id}-REJECTED`} onClick={()=>change("application",x.id,"REJECTED")}><XCircle size={16}/> Reject</button>}</div></div></div>)}</div>}
function BookingModal({item,onClose}){return<Modal title={item.listingTitle||"Transaction"} eyebrow={`${pretty(item.bookingType)} · ${item.status}`} onClose={onClose}><Details item={item}/><h3 className="section-title mt-6">Status timeline</h3><div className="mt-4"><StatusTimeline history={item.statusHistory} current={item.status}/></div></Modal>}
function ApplicationModal({item,onClose}){return<Modal title={item.listingTitle||"Job application"} eyebrow={`JOB · ${item.status}`} onClose={onClose}><div className="rounded-2xl bg-slate-50 p-5"><p className="text-xs font-bold uppercase tracking-wider text-slate-400">Applicant</p><p className="mt-1 text-lg font-black">{item.applicantName||"Applicant"}</p>{item.applicantMobile&&<p className="mt-2 flex items-center gap-2 text-sm text-slate-500"><Phone size={14}/>{item.applicantMobile}</p>}{item.applicantEmail&&<p className="mt-1 flex items-center gap-2 text-sm text-slate-500"><Mail size={14}/>{item.applicantEmail}</p>}</div>{item.interviewDate&&<div className="mt-4 rounded-2xl border border-indigo-100 bg-indigo-50 p-4"><p className="text-xs font-bold uppercase tracking-wider text-indigo-500">Interview</p><p className="mt-1 font-black text-indigo-900">{new Date(item.interviewDate).toLocaleString("en-IN")}</p>{item.interviewNotes&&<p className="mt-1 text-sm text-indigo-700">{item.interviewNotes}</p>}</div>}<h3 className="section-title mt-6">Status timeline</h3><div className="mt-4"><StatusTimeline history={item.statusHistory} current={item.status}/></div>{item.coverLetter&&<div className="mt-6"><p className="text-xs font-bold uppercase tracking-wider text-slate-400">Cover letter</p><p className="mt-2 rounded-2xl border border-slate-200 p-4 text-sm leading-6 text-slate-700 whitespace-pre-wrap">{item.coverLetter}</p></div>}</Modal>}
function Details({item}){const d=item.details||{};return<div className="grid gap-3 sm:grid-cols-2">{[["Customer",item.customerName||item.contactName],["Mobile",item.customerMobile||item.contactNumber],["Date",item.bookingDate],["Time",item.startTime],["Quantity",item.quantity],["Amount",item.amount!=null?`₹${Number(item.amount).toLocaleString("en-IN")}`:null],["Address",item.address],["Notes",item.notes]].concat(Object.entries(d).map(([k,v])=>[k,String(v)])).filter(([,v])=>v!==null&&v!==undefined&&v!=="").map(([k,v])=><div key={k} className="rounded-xl bg-slate-50 p-3"><p className="text-xs font-bold uppercase tracking-wider text-slate-400">{k}</p><p className="mt-1 break-words text-sm font-semibold text-slate-700">{String(v)}</p></div>)}</div>}
function Modal({title,eyebrow,onClose,children}){return<div className="fixed inset-0 z-50 grid place-items-center bg-slate-950/60 p-4"><div className="max-h-[92vh] w-full max-w-2xl overflow-y-auto rounded-3xl bg-white p-5 shadow-2xl sm:p-7"><div className="flex items-start justify-between gap-4"><div><p className="eyebrow">{eyebrow}</p><h2 className="mt-1 text-2xl font-black">{title}</h2></div><button className="icon-btn" onClick={onClose}>×</button></div><div className="mt-6">{children}</div></div></div>}
function Stat({icon:Icon,label,value}){return<div className="card p-5"><div className="grid h-10 w-10 place-items-center rounded-xl bg-slate-100"><Icon size={19}/></div><p className="mt-4 text-xs font-bold uppercase tracking-wider text-slate-400">{label}</p><p className="mt-1 text-2xl font-black">{value}</p></div>}function Tab({active,onClick,icon:Icon,label}){return<button onClick={onClick} className={`flex items-center gap-2 rounded-xl px-4 py-3 text-sm font-bold ${active?"bg-slate-950 text-white":"text-slate-500 hover:bg-slate-50"}`}><Icon size={17}/>{label}</button>}function Filter({active,onClick,text}){return<button onClick={onClick} className={`whitespace-nowrap rounded-full px-3 py-1.5 text-xs font-bold ${active?"bg-slate-950 text-white":"bg-slate-100 text-slate-500"}`}>{text}</button>}function Empty({icon:Icon,title,text}){return<div className="p-12 text-center sm:p-16"><div className="mx-auto grid h-14 w-14 place-items-center rounded-2xl bg-slate-100"><Icon size={25}/></div><h3 className="mt-4 font-black">{title}</h3><p className="mx-auto mt-2 max-w-md text-sm leading-6 text-slate-500">{text}</p></div>}function dedupe(a){return[...new Map(a.filter(x=>x?.id).map(x=>[x.id,x])).values()]}
